#include <iostream>
using namespace std;

class Box {
    int* data_;

public:
    Box(int v) : data_(new int(v)) {}
    Box(const Box& other) : data_(new int(*other.data_)) {}
    ~Box() { delete data_; }
    void set(int v) { *data_ = v; }
    int get() const { return *data_; }
};

int main() {
    Box a(5);
    Box b = a;
    b.set(9);
    cout << a.get() << " " << b.get() << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

class Scores {
    vector<int> data_;

public:
    void add(int v) { data_.push_back(v); }
    int count() const { return static_cast<int>(data_.size()); }
};

int main() {
    Scores a;
    a.add(10);
    a.add(20);
    Scores b = a;
    b.add(30);
    cout << a.count() << " " << b.count() << endl;
    return 0;
}

